namespace XnaReborn.Migrator.Shims;

/// <summary>
/// The C# source of the SharpDX math stand-ins in <c>XnaReborn.Compat</c> (sharpdx-toolkit task 14). The types sit in
/// <c>Microsoft.Xna.Framework</c>, the namespace the Toolkit rewriter turns <c>using SharpDX;</c> into, so game code compiles unchanged.
/// MonoGame has no type of these names, so nothing clashes.
/// </summary>
internal static class ShimSharpDxSources
{
    /// <summary>Path of the generated file inside the shim library.</summary>
    internal const string FileName = "SharpDxMath.cs";

    /// <summary>The type names the stand-ins provide.</summary>
    internal static readonly string[] Types = ["Color3", "Color4", "RectangleF"];

    /// <summary>Namespace of the stand-ins.</summary>
    internal const string Namespace = "Microsoft.Xna.Framework";

    /// <summary>The stand-in source: <c>RectangleF</c>, <c>Color3</c> and <c>Color4</c> with the members small games use.</summary>
    internal const string Source = """
        // Generated by XNA Reborn. Small stand-ins for SharpDX math types that MonoGame does not provide.
        using System;

        namespace Microsoft.Xna.Framework
        {
            /// <summary>A rectangle with float fields, like SharpDX.RectangleF.</summary>
            public struct RectangleF : IEquatable<RectangleF>
            {
                public float X;
                public float Y;
                public float Width;
                public float Height;

                public RectangleF(float x, float y, float width, float height)
                {
                    X = x;
                    Y = y;
                    Width = width;
                    Height = height;
                }

                public float Left => X;

                public float Top => Y;

                public float Right => X + Width;

                public float Bottom => Y + Height;

                public Vector2 Center => new Vector2(X + Width / 2f, Y + Height / 2f);

                public bool Contains(float x, float y) => x >= X && x < Right && y >= Y && y < Bottom;

                public bool Contains(Vector2 point) => Contains(point.X, point.Y);

                public bool Intersects(RectangleF other) => other.X < Right && X < other.Right && other.Y < Bottom && Y < other.Bottom;

                /// <summary>Rounds each field down to a whole number.</summary>
                public Rectangle ToRectangle() => new Rectangle((int)X, (int)Y, (int)Width, (int)Height);

                public static explicit operator Rectangle(RectangleF value) => value.ToRectangle();

                public static implicit operator RectangleF(Rectangle value) => new RectangleF(value.X, value.Y, value.Width, value.Height);

                public bool Equals(RectangleF other) => X == other.X && Y == other.Y && Width == other.Width && Height == other.Height;

                public override bool Equals(object? obj) => obj is RectangleF other && Equals(other);

                public override int GetHashCode() => HashCode.Combine(X, Y, Width, Height);

                public static bool operator ==(RectangleF left, RectangleF right) => left.Equals(right);

                public static bool operator !=(RectangleF left, RectangleF right) => !left.Equals(right);
            }

            /// <summary>A color with three float channels, like SharpDX.Color3.</summary>
            public struct Color3 : IEquatable<Color3>
            {
                public float Red;
                public float Green;
                public float Blue;

                public Color3(float red, float green, float blue)
                {
                    Red = red;
                    Green = green;
                    Blue = blue;
                }

                public Vector3 ToVector3() => new Vector3(Red, Green, Blue);

                public static implicit operator Vector3(Color3 value) => value.ToVector3();

                public bool Equals(Color3 other) => Red == other.Red && Green == other.Green && Blue == other.Blue;

                public override bool Equals(object? obj) => obj is Color3 other && Equals(other);

                public override int GetHashCode() => HashCode.Combine(Red, Green, Blue);

                public static bool operator ==(Color3 left, Color3 right) => left.Equals(right);

                public static bool operator !=(Color3 left, Color3 right) => !left.Equals(right);
            }

            /// <summary>A color with four float channels from 0 to 1, like SharpDX.Color4.</summary>
            public struct Color4 : IEquatable<Color4>
            {
                public float Red;
                public float Green;
                public float Blue;
                public float Alpha;

                public Color4(float red, float green, float blue, float alpha)
                {
                    Red = red;
                    Green = green;
                    Blue = blue;
                    Alpha = alpha;
                }

                public Color4(Vector4 value)
                    : this(value.X, value.Y, value.Z, value.W)
                {
                }

                public Color4(Color value)
                    : this(value.R / 255f, value.G / 255f, value.B / 255f, value.A / 255f)
                {
                }

                public static Color4 Black => new Color4(0f, 0f, 0f, 1f);

                public static Color4 White => new Color4(1f, 1f, 1f, 1f);

                public Vector4 ToVector4() => new Vector4(Red, Green, Blue, Alpha);

                /// <summary>Converts to a byte color. Each channel is clamped to 0..1 first.</summary>
                public Color ToColor() => new Color(ToVector4());

                public static implicit operator Vector4(Color4 value) => value.ToVector4();

                public static implicit operator Color4(Vector4 value) => new Color4(value);

                public static implicit operator Color4(Color value) => new Color4(value);

                public static explicit operator Color(Color4 value) => value.ToColor();

                public bool Equals(Color4 other) => Red == other.Red && Green == other.Green && Blue == other.Blue && Alpha == other.Alpha;

                public override bool Equals(object? obj) => obj is Color4 other && Equals(other);

                public override int GetHashCode() => HashCode.Combine(Red, Green, Blue, Alpha);

                public static bool operator ==(Color4 left, Color4 right) => left.Equals(right);

                public static bool operator !=(Color4 left, Color4 right) => !left.Equals(right);
            }
        }
        """;
}
